import sys,json,hashlib,pathlib,shutil
mem={p.split()[0].rstrip(':'):int(p.split()[1])*1024 for p in pathlib.Path('/proc/meminfo').read_text().splitlines() if p.startswith('MemAvailable:')}
guard={'mem_available_bytes':mem['MemAvailable'],'private_free_bytes':shutil.disk_usage('/dev').free,'filesystem_writes':0,'purpose':'verify original TasteTable capsule bytes only; no application import or execution'}
if guard['mem_available_bytes']<2*1024**3 or guard['private_free_bytes']<128*1024**2: raise RuntimeError('Fileless original-input verification guard refused')
def pins(b): return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()}
raw=sys.argv[1].encode('utf-8')
cap=pins(raw)
assert cap=={'bytes':55094,'sha256':'724be9c59600c28e0f6a69fefcbf635a321aade0ef5f84c5d402204285224344','git_blob':'f5ceed23b810957cf8e4cb36083fd519f9f03a2d'},cap
obj=json.loads(raw); results=[]
for f in obj['files']:
    actual=pins(f['content'].encode('utf-8'))
    assert actual=={k:f[k] for k in ('bytes','sha256','git_blob')},f['path']
    results.append({'path':f['path'],**actual,'exact':True})
assert len(results)==11
print(json.dumps({'capsule':cap,'members':results,'guard':guard,'all_exact':True},ensure_ascii=False))
